import sys

def main():
    try:
        line = sys.stdin.readline()
        while line and not line.strip():
            line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    points = []
    colors = []

    for _ in range(n):
        if len(colors) == 0:
            x, y = 0, 0
        else:
            min_x = min(p[0] for p in points)
            max_x = max(p[0] for p in points)
            min_y = min(p[1] for p in points)
            max_y = max(p[1] for p in points)

            candidates = []
            for dx in [-1, 1]:
                for dy in [-1, 1]:
                    nx, ny = min_x - 1 + dx, min_y - 1 + dy
                    if 0 <= nx <= 10**9 and 0 <= ny <= 10**9 and (nx, ny) not in [(p[0], p[1]) for p in points]:
                        candidates.append((nx, ny))
                    nx, ny = max_x + 1 + dx, max_y + 1 + dy
                    if 0 <= nx <= 1000000000 and 0 <= ny <= 1000000000 and (nx, ny) not in [(p[0], p[]) for p in points]:
                        candidates.append((nx, ny))

            if not candidates:
                for x in range(0, 1000000001):
                    for y in range(0, 1000000000):
                        if (x, y) not in [(p[0], p[1]) for p in [points]]:
                            candidates.append((x, y))
                            break
                    if candidates:
                        break

            if candidates:
                x, y = candidates[0]
            else:
                x, y = 0, 0

        sys.stdout.write(f"{x} {y}\n")
        sys.stdout.flush()

        try:
            color_line = sys.stdin.readline().strip()
            while not color_line:
                color_line = sys.stdin.readline().strip()
            color = color_line
        except EOFError:
            break

        points.append((x, y))
        colors.append(color)

    black_points = [p for i, p in enumerate(points) if colors[i] == 'black']
    white_points = [p for i, p in enumerate(points) if colors[i]] == 'white']

    if not black_points or not white_points:
        x1, y1 = 0, 0
        x2, y2 = 1, 1
    else:
        sum_bx = sum(p[0] for p in black_points)
        sum_by = sum(p[1] for p in black_points)
        sum_wx = sum(p[0] for p in white_points)
        sum_wy = sum(p[1] for p in white_points)

        cx_b = sum_bx // len(black_points)
        cy_b = sum_by // len(black_points)
        cx_w = sum_wx // len(white_points)
        cy_w = sum_wy // len(white_points)

        mid_x = (cx_b + cx_w) // 2
        mid_y = (cy_b + cy_w) // 2

        dx = cx_w - cx_b
        dy = cy_w - cy_b

        if abs(dx) > abs(dy):
            x1, y1 = mid_x - 1, mid_y
            x2, y2 = mid_x + 1, mid_y
        else:
            x1, y1 = mid_x, mid_y - 1
            x2, y2 = mid_x, mid_y + 1

    sys.stdout.write(f"{x1} {y1} {x2} {y2}\n")
    sys.stdout.flush()

if __name__ == "__main__":
    main()
